 p.set_viewport_size({'width':360,'height':800});box.scroll_into_view_if_needed();p.screenshot(path='/tmp/customer-sites144-phone.png',full_page=True)
 box.locator('[data-customer-site-add]').click();p.wait_for_selector('[name=customer_id]');assert p.input_value('[name=customer_id]')==ids['id'];assert p.input_value('[name=name]')=='';assert p.evaluate(snap)==before
